def construct_huffman_tree(frequency_of_character): 
    frequency_heap = [[weight, [symbol, '']] for symbol, weight in frequency_of_character.items()] 

    hops_heap = frequency_heap 
    while len(frequency_heap) > 1: 
        low = heapq.heappop(frequency_heap) 
        high = heapq.heappop(frequency_heap) 
        for value in low[1:]: 
            value[1] = '0' + value[1] 
        for value in high[1:]: 
            value[1] = '1' + value[1] 
        heapq.heappush(frequency_heap, [low[0] + high[0]] + low[1:] + high[1:]) 

    return frequency_heap 

def generate_huffman_code(string): 
    frequency_of_character = store_frequency_of_characters(string)
    frequency_heap = construct_huffman_tree(frequency_of_character) 
    huffman_codes = {} 

    for i in frequency_heap[0][1:]: 
        huffman_codes[i[0]] = i[1] 

    encoded_string = "" 
    for character in string: 
        encoded_string  = encoded_string + huffman_codes[character] 
