using namespace std;

// Structure for representing a node in the expression tree
struct Node {
    char value;
    Node *left, *right;
};

// Create a node in the expression tree
Node* createNode(char value) {
    Node *node = new Node;
    node->value = value;
    node->left =  node->right = nullptr;
    return node;
}

// Find an operator for creating the expression tree
int find_operator(string expr) {
    int max_precedence = 0;
    int position = -1;
    // Map of operators and their precedences
    map<char, int> order{{'+', 0}, {'-', 1}, {'*', 2}, {'/', 3}};

    for (int i = 0; i <expr.length() ; i++) {
        int precedence = order[expr[i]];
        // If current operator has greater precedence, then update max_precedence
        if (precedence > max_precedence) {
            max_precedence = precedence;
            position = i;
        }
    }
    return position; 
}

// Traverse the generated expression tree
void traverse(Node *node) {
    if (node) {
        traverse(node->left);
        cout << node->value << " ";
        traverse(node->right);
    }
}

int main() {
    string expression = "2 + 3 * 5";
    int pos = find_operator(expression);
    Node *root = createNode(expression[pos]);
    root->left = createNode(expression[pos-1]);
    root->right = createNode(expression[pos+1]);

    // Traverse the expression tree
    traverse(root);
    return 0;
}

