def countAdjacentOffDiagonalSquares(matrix):
	count = 0
	for i in range(len(matrix)):
		for j in range(len(matrix)):
			# check if current element is 1
			if(matrix[i][j] == 1):
				# check if top row is valid
				if(i - 1 >= 0):
					# check if left column is valid
					if(j - 1 >= 0):
						# check if top left element is 1
						if(matrix[i - 1][j - 1] == 1):
							count += 1

					# check if right column is valid
					if(j + 1 < len(matrix)):
						# check if top right element is 1
						if(matrix[i - 1][j + 1] == 1):
							count += 1

				# check if bottom row is valid
				if(i + 1 < len(matrix)):
					# check if left column is valid
					if(j - 1 >= 0):
						# check if bottom left element is 1
						if(matrix[i + 1][j - 1] == 1):
							count += 1

					# check if right column is valid
					if(j + 1 < len(matrix)):
						# check if bottom right element is 1
						if(matrix[i + 1][j + 1] == 1):
							count += 1
	return count

