#include <algorithm>

// Function to produce a set of clusters and identify outliers
// in a given dataset
vector< vector<double> > clusterData(vector< vector<double> >& data) {
	// number of attributes in the given dataset
	int n = data[0].size();

	// an array to hold the means of all the clusters
	vector< vector<double> > means;

	// loop until no more outliers left or
	// all the points in the dataset are clustered
	while (true) {
		// a vector to hold the max attribute values of the dataset
		vector<double> maxAttrs;
		for (int i = 0; i < n; i++) 
			maxAttrs.push_back(-INFINITY);

		// loop for each point in the dataset
		for (int i = 0; i < data.size(); i++) {
			// loop for each attribute of the point
			for (int j = 0; j < n; j++)
				maxAttrs[j] = max(maxAttrs[j], data[i][j]);
		}

		// append the mean of the points as the new cluster
		means.push_back(maxAttrs);

		// loop for each point in the dataset
		for (int i = 0; i < data.size(); i++) {
			// loop for each cluster
			for (int j = 0; j < means.size(); j++) {
				// check if the point lies within the cluster range
				bool inside = true;
				for (int k = 0; k < n; k++) 
					if (data[i][k] > means[j][k]) {
						inside = false;
						break;
					}

				// if the point is within the cluster, add it to the cluster
				if (inside) {
					// remove it from the dataset
					data.erase(data.begin() + i);

					// update the mean of the cluster
					means[j] = mean(means[j], maxAttrs, n);
					i--;
					break;
				}
			}
		}

		// break the loop if all the points are clustered
		// or no more outliers left
		if (data.empty())
			break;
	}

	// return the set of clusters
	return means;
}

