def str_search(s, substr):
    if len(substr) > len(s):
        return -1
    i, j = 0, 0
    while i < len(s) and j < len(substr):
        if s[i] == substr[j]:
            i += 1
            j += 1
        else:
            i -= j
            j = 0
        if j == len(substr):
            return i - j
        else:
            return -1

