def compress(string):
    if len(string) <= 2:
        return string

    result = ""
    i = 0
    while i < len(string):
        result += string[i]
        count = 1
        while i < len(string) - 1 and string[i] == string[i + 1]:
            count += 1
            i += 1
        if count > 2:
            result += str(count)
        i += 1
    return result

