class Trees { 

    public static long numTrees(int n) 
    { 
        long C[] = new long[n + 1]; 

        // For a single node tree, there is one 
        // possible tree 
        C[0] = 1; 
        C[1] = 1; 

        for (int i = 2; i <= n; i++) { 
            for (int j = 0; j < i; j++) 
                C[i] += C[j] * C[i - j - 1]; 
        } 

        return C[n]; 
    } 

    public static void main(String[] args) 
    { 
        int n = 4; 
        System.out.println(numTrees(n)); 
    } 
}

