import math

def entropy(s):
    entropy = 0
    # get frequency of each character
    char_freq = dict() 
    for c in s:
        if c in char_freq:
            char_freq[c] += 1
        else:
            char_freq[c] = 1

    # calculate the entropy
    for freq in char_freq.values():
        p = freq/len(s)
        entropy += -p * math.log2(p)  

    return entropy

