def evaluate_expression(expression):
    stack = []
    for char in expression:
        if char.isdigit():
            stack.append(int(char))
        else:
            num1 = stack.pop()
            num2 = stack.pop()
            if char is '+':
                res = num1 + num2
            elif char is '-':
                res = num2 - num1
            elif char is '*':
                res = num1 * num2
            elif char is '/':
                res = num2 / num1
            stack.append(res)
    return stack.pop()

