def get_mean_median_mode(lst):
  mean = 0  
  for num in lst:
    mean += num
  mean /= len(lst)

  sorted_lst = sorted(lst)
  if len(sorted_lst) % 2 == 0:
    median = (sorted_lst[len(sorted_lst)//2 - 1] + sorted_lst[len(sorted_lst)//2]) // 2
  else:
    median = sorted_lst[len(sorted_lst)//2]

  mode = sorted_lst[0]
  max_frequency = 1
  current_frequency = 1
  for i in range(1, len(sorted_lst)):
    if sorted_lst[i] == sorted_lst[i-1]:
      current_frequency += 1
      if current_frequency > max_frequency:
        max_frequency = current_frequency
        mode = sorted_lst[i]
    else:
      current_frequency = 1

  return mean, median, mode

