public static boolean detectCycle(ListNode head) {
    ListNode slow = head;
    ListNode fast = head;
    int loopCounter = 0;

    if (head == null){
        return false;
    }
    if (head.next == null){
        return false;
    }

    while (loopCounter < 100){
        slow = slow.next;
        fast = fast.next.next;

        if (fast == slow)
            return true;
        loopCounter++;
    }
    return false;
}

