struct Node
{
    int data;
    Node* left;
    Node* right;
};

class BinarySearchTree
{
    Node* root;
    // Utility Functions
    Node* createNode(int item);
    Node* insert(Node* root, int item);
    Node* search(Node* root, int item);
    void inOrder(Node* node); 

public: 
    BinarySearchTree() {root = NULL;} 
    void search(int item); 
    void insert(int item); 
	void inOrder(); 
}; 

// Creating a node
Node* BinarySearchTree::createNode(int item)
{
    Node* newNode = new Node;
    newNode->data = item;
    newNode->left = NULL;
    newNode->right = NULL;
    return newNode;
}

// Inserting item in BST
Node* BinarySearchTree::insert(Node* root, int item)
{
    if (root == NULL)
        return createNode(item);
    if (item < root->data)
        root->left = insert(root->left, item);
    else if (item > root->data)
        root->right = insert(root->right, item);
    return root;
} 

// Searcing for an element in BST
Node* BinarySearchTree::search(Node* root, int item)
{
    if (root == NULL)
        return NULL;
    // Found item
    if (item == root->data)
        return root;
    if (item < root->data)
        return search(root->left, item);
    else 
        return search(root->right, item);
}

// Searching an item
void BinarySearchTree::search(int item)
{
    if (search(root, item) != NULL)
        cout << "Yes" << endl;
    else 
        cout << "No" << endl;
