// An in-place Bubble Sort sort algorithm
function bubbleSort(arr) {
    let isSorted = false;
    let lastUnsorted = arr.length - 1;

    while (!isSorted) {
        isSorted = true;
        for (let i = 0; i < lastUnsorted; i++) {
            if (arr[i] > arr[i + 1]) {
                let temp = arr[i];
                arr[i] = arr[i + 1];
                arr[i + 1] = temp;
                isSorted = false;
            }
        }
        lastUnsorted--;
    }
    return arr;
}


