struct Heap {
 int size;
 int capacity;
 int *arr;
};

struct Heap * createHeap(int capacity) {
 struct Heap *h = (struct Heap *)malloc(sizeof(struct Heap));
 h->size = 0;
 h->capacity = capacity;
 h->arr = (int *)malloc(sizeof(int) * h->capacity);
 return h;
}

void minHeapify(struct Heap *h, int i) {
 int l = 2 * i + 1;
 int r = 2 * i + 2;
 int smallest = i;
 if (l < h->size && h->arr[l] < h->arr[smallest])
 smallest = l;
 if (r < h->size && h->arr[r] < h->arr[smallest])
 smallest = r;
 if (smallest != i) {
 int temp = h->arr[smallest];
 h->arr[smallest] = h->arr[i];
 h->arr[i] = temp;
 minHeapify(h, smallest);
 }
}

void buildHeap(struct Heap *h, int arr[], int n) {
 int i;
 if (h == NULL)
 return;
 while (n > h->capacity) {
 h->capacity *= 2;
 h->arr = (int *)realloc(h->arr, sizeof(int) * (h->capacity));
 }
 for (i = 0; i < n; i++)
 h->arr[i] = arr[i];
 h->size = n;
 for (int i = (n - 1) / 2; i >= 0; --i)
 minHeapify(h, i);
}

