function median(arr) {
    // Sort the array
    const sorted = arr.sort((a, b) => a - b);

    // If the length of the array is even, take the two middle values and calculate the mean 
    if (sorted.length % 2 === 0) {
        const mid1 = sorted[sorted.length / 2];
        const mid2 = sorted[(sorted.length / 2) - 1];

        return (mid1 + mid2) / 2;
    } else {
        // If the length of the array is odd, the median is the middle value
        return sorted[Math.floor(sorted.length / 2)];
    }
}

