def classify(instance, root_node):
    """Classify an instance using the decision tree"""
    if root_node.children == []:
        # leaf node
        return root_node.class_label

    else:
        # internal node
        attr_value = instance[root_node.attr_name]
        for node in root_node.children:
            if node.attr_name == attr_value:
