def longestSubsequence(target, strings):
    longestSubsequence = ""
    longestSubsequenceLength = 0

    for string in strings:
        stringIndex = 0
        sequenceIndex = 0
        while (stringIndex < len(string) and sequenceIndex < len(target)):
            if string[stringIndex] == target[sequenceIndex]:
                stringIndex += 1

            sequenceIndex += 1

        if (stringIndex == len(string)):
            if (stringIndex > longestSubsequenceLength):
                longestSubsequenceLength = stringIndex
                longestSubsequence = string

    return longestSubsequence

class HashMap:
    def __init__(self):
        self.size = 10
        self.map = [None] * self.size

    def _get_hash(self, key):
        hash = 0
        for char in key:
            hash += ord(char)
        return hash % self.size

    def add(self, key, value):
        key_hash = self._get_hash(key)
        key_value = [key, value]

        if self.map[key_hash] is None:
            self.map[key_hash] = list([key_value])
            return True
        else:
            for pair in self.map[key_hash]:
                if pair[0] == key:
                    pair[1] = value
                    return True
            self.map[key_hash].append(key_value)
            return True

    def get(self, key):
        key_hash = self._get_hash(key)
        if self.map[key_hash] is not None:
            for pair in self.map[key_hash]:
                if pair[0] == key:
                    return pair[1]
        return None

