def findClosestPair(points):
    '''This function returns the closest pair among a set of points.'''
    min_distance = float("inf")
    closest_pair = None

    for i in range(len(points)):
        for j in range(i + 1, len(points)):
            x1, y1 = points[i]
            x2, y2 = points[j]

            distance = ((x1 - x2) ** 2 + (y1 - y2) ** 2) ** 0.5
