def search_occurrences(arr, target):

    # find the start and end indices of the target 
    start = 0 
    end = len(arr) - 1 
    first_idx = -1
    last_idx = -1

    # Start loop from both ends to find start and end indices of target 
    while start <= end: 
        mid = (start + end)//2

        if arr[mid] == target and (mid == 0 or arr[mid-1] < target):
            first_idx = mid 
            break 
        elif target > arr[mid]: 
            start = mid + 1
        else: 
            end = mid - 1

    start = 0 
    end = len(arr) - 1 
    while start <= end: 
        mid = (start + end)//2

        if arr[mid] == target and (mid == (len(arr) - 1) or arr[mid+1] > target): 
            last_idx = mid 
            break 
        elif target < arr[mid]: 
            end = mid - 1
        else: 
            start = mid + 1

    if first_idx != -1 and last_idx != -1: 
        return last_idx - first_idx + 1
    else: 
        return 0

