def longest_common_subsequence(str1, str2):
    n = len(str1)
    m = len(str2)
    L = [[0]*(m+1) for i in range(n+1)]
    for i in range(1, n+1):
        for j in range(1, m+1):
            if str1[i-1] == str2[j-1]:
                L[i][j] = L[i-1][j-1] + 1 
            else:
                L[i][j] = max(L[i-1][j], L[i][j-1])
    lcs_length = L[n][m]
    lcs = ['']*lcs_length
    i = n
    j = m
    while i > 0 and j > 0:
        if str1[i-1] == str2[j-1]:
            lcs[lcs_length-1] = str1[i-1]
            i -= 1
            j -= 1
            lcs_length -= 1
        elif L[i-1][j] > L[i][j-1]:
            i -= 1
        else:
            j -= 1
    return lcs

