def fuzzy_search(query_string):
    query_string = query_string.lower()
    results = []
    # Split query string into words
    words = query_string.split()
    for word in words:
        for char in word:
            # Replace any non-word character with a wildcard
            if not char.isalpha():
                word = word.replace(char, '.*')

            # replace any consecutive non-word characters with a single wildcard
            word = re.sub(r'[\W]+', '.*', word)

            results.append(word)
    # Join words with a wildcard in between 
    return ".*".join(results)

def edit_distance(x, y): 
    # Create a distance matrix
    matrix = [[0 for i in range(len(x) + 1)] for j in range(len(y) + 1)] 

    # Iterate through the matrix to get the edit distance between two strings 
    for i in range(len(x) + 1): 
        for j in range(len(y) + 1): 

            # If either string is empty, the distance is the length of the other
            if i == 0: 
                matrix[i][j] = j  
            elif j == 0: 
                matrix[i][j] = i   

            # Check if characters at position i and j match
            # If they match, the cost is 0
            # If they don't match, add 1 to the distance
            elif x[i - 1] == y[j - 1]: 
                matrix[i][j] = matrix[i-1][j-1] 
            else:
                matrix[i][j] = 1 + min(matrix[i][j-1],   
                                   matrix[i-1][j],   
                                   matrix[i-1][j-1]) 

    return matrix[len(x)][len(y)]


