def levenshtein_distance(string_1, string_2):
    rows = len(string_1) + 1
    cols = len(string_2) + 1
    dp_table = [[0 for i in range(cols)] for j in range(rows)] 

    for i in range(1, rows): 
        dp_table[i][0] = i
    for j in range(1, cols): 
        dp_table[0][j] = j

    for j in range(1, cols): 
        for i in range(1, rows): 
            if string_1[i-1] == string_2[j-1]: 
                cost = 0 
            else: 
                cost = 1
            dp_table[i][j] = min(dp_table[i-1][j] + 1, 
                               dp_table[i][j-1] + 1,  
                               dp_table[i-1][j-1] + cost)

    return dp_table[-1][-1]

