class MaxHeap { 

    private int[] Heap; 
    private int size; 
    private int maxsize; 

    // Constructor to initialize an empty max heap 
    public MaxHeap(int maxsize) { 
        this.maxsize = maxsize; 
        this.size = 0; 
        Heap = new int[this.maxsize + 1]; 
        Heap[0] = Integer.MAX_VALUE; 
    } 

    // A method to return the parent of a node present at index 
    private int parent(int pos) { 
        return pos / 2; 
    } 

    // Method to return the index of the left child 
    private int leftChild(int pos) { 
        return (2 * pos); 
    } 

    // Method to return the index of the right child 
    private int rightChild(int pos) { 
        return (2 * pos) + 1; 
    } 

    // Method that returns true if the passed node is a leaf node 
    private boolean isLeaf(int pos) { 
        if (pos >= (size / 2) && pos <= size) { 
            return true; 
        } 
        return false; 
    } 

    // Method to swap two nodes of the heap 
    private void swap(int fpos, int spos) { 
        int tmp; 
        tmp = Heap[fpos]; 
        Heap[fpos] = Heap[spos]; 
        Heap[spos] = tmp; 
    }

    // A recursive method to max heapify the given subtree. 
    private void maxHeapify(int pos) 
    { 
        // If the node is a non-leaf node and smaller than
        // any of its child 
        if (!isLeaf(pos)) { 
            if (Heap[pos] < Heap[leftChild(pos)] 
                || Heap[pos] < Heap[rightChild(pos)]) { 

                // Swap with the left child and max heapify 
                // the left child 
                if (Heap[leftChild(pos)] > Heap[rightChild(pos)]) { 
                    swap(pos, leftChild(pos)); 
                    maxHeapify(leftChild(pos)); 
                } 

                // Swap with the right child and max heapify 
                // the right child 
                else { 
                    swap(pos, rightChild(pos)); 
                    maxHeapify(rightChild(pos)); 
                } 
            } 
        } 
    } 

    // Method to insert a node into the heap 
    public void insert(int element) { 
        Heap[++size] = element; 

        // Traverse up and fix violated property 
        int current = size; 
        while (Heap[current] > Heap[parent(current)]) { 
            swap(current, parent(current)); 
            current = parent(current); 
        } 
    }

     // Method to print the contents of the heap 
    public void print() { 
        for (int i = 1; i <= size / 2; i++) { 
            System.out.print(
             "PARENT : " + Heap[i] + " LEFT CHILD : " + Heap[2 * i] 
                     + " RIGHT CHILD :" + Heap[2 * i + 1]); 
            System.out.println(); 
        } 
    }

    // Method to build the max heap tree 
    public void maxHeap() { 
        for (int pos = (size / 2); pos >= 1; pos--) { 
            maxHeapify(pos); 
        } 
    } 

    // Method to remove and return the root element 
    public int remove() { 
        int popped = Heap[1]; 
        Heap[1] = Heap[size--]; 
        maxHeapify(1); 
        return popped; 
    } 
}

