        if exp[i] == '*' or exp[i] == '+': 
            op1 = operand.pop() 
            op2 = operand.pop() 
            result = eval(op1 + exp[i] + op2) 
            operand.append(str(result)) 
        else:  
            operand.append(exp[i]) 
