class SnakeGame():
    def __init__(self):
        # Initialize game board
        self.board = self.initialize_board()
        # Initialize snake position
        self.snake_position = self.start_position()
        # Initialize fruit position
        self.fruit_position = self.place_fruit()
        # Set the game running
        self.running = True

    def initialize_board(self):
        # Initialize a board with width and height
        board = [[0 for w in range(0,20)] for h in range(0,20)]
        return board

    def start_position(self):
        # Initialize the snake head at the middle of the board
        x = int(len(self.board[0])/2)
        y = int(len(self.board)/2)
        return [x, y]

    def place_fruit(self):
        # Place the fruit in a random position
        while True: 
            x = random.randrange(0, 20)
            y = random.randrange(0, 20)
            if self.board[y][x] == 0:
                return [x, y]

    def move_snake(self, direction):
        # Move the snake in the given direction
        x_move, y_move = self.get_direction_vectors(direction)
        x, y = self.snake_position
        x += x_move
        y += y_move
        self.snake_position = [x, y]

    def get_direction_vectors(self, direction):
        # Create a dictionary to store the direction vectors
        direction_vectors = {
            'left': (-1, 0),
            'right': (1, 0),
            'up': (0, -1),
            'down': (0, 1)
        }
        # Return the appropriate direction vector
        return direction_vectors.get(direction)

    def render_board(self):
        # Render the board state
        print('+' + '-'*len(self.board[0]) + '+')
        for row in self.board:
            print('|' + ''.join(map(self.render_cell, row)) + '|')
        print('+' + '-'*len(self.board[0]) + '+')

    def render_cell(self, cell):
        # Render the cell state
        if cell == 0:
            return ' '
        elif cell == 1:
            return 'S'
        elif cell == 2:
            return 'F'

