struct Node 
{ 
    int data; 
    struct Node* next; 
}; 

// Function to return the count of 
// the given element in linked list 
int getCount(struct Node* head, int data) 
{ 
    // Initialise count 
    int count = 0; 

    // Iterate untilt the end of the list 
    while (head != NULL) { 

        // If data matches, increment count 
        if (head->data == data) 
            count+=1; 

        // Move the pointer of the linked list 
        head = head->next; 
    } 

    return count; 
} 

