public class ConvertArrayToBST {  
    static class Node {  
        int data;  
        Node left, right;  

        Node(int item) {  
            data = item;  
            left = right = null;  
        }  
    }  
    static Node root;  

    // Method to construct a BST  
    static Node constructBST(int[] arr, int start, int end) {  
        if (start > end) {  
            return null;  
        }  
        int mid = (start + end) / 2;  
        Node node = new Node(arr[mid]);  
        node.left = constructBST(arr, start, mid - 1);  
        node.right = constructBST(arr, mid + 1, end);  
        return node;  
    }  

    static void preorder(Node node) {  
        if (node == null) {  
            return;  
        }  
        System.out.print(node.data + " ");  
        preorder(node.left);  
        preorder(node.right);  
    }  
    public static void main(String[] args) {
        int[] arr = { 3, 11, 7, 12, 5, 0 };  
        int n = arr.length; 
