def knapsack(items, W):
  n = len(items)

  # stores maximum benefit value
  max_benefit = 0

  # matrix to store results of sub problems
  cache = [[0 for x in range(W+1)] for x in range(n+1)]

  # Base case
  for i in range(n+1):
    for w in range(W+1):
      if i == 0 or w == 0:
        cache[i][w] = 0
      elif items[i-1][0] <= w:
        cache[i][w] = max(items[i-1][1] + cache[i-1][w-items[i-1][0]],  cache[i-1][w])
      else:
        cache[i][w] = cache[i-1][w]

  # find solution
  res = []
  w = W
  for i in range(n, 0, -1):
    if cache[i][w] != cache[i-1][w]:
      res.append(items[i-1])
      w -= items[i-1][0]

  # Return result
  return res

