def find_lcs(str1, str2):
    m = len(str1)
    n = len(str2)

    # set up the memoization table
    memoization_table = [[ 0 for x in range(n+1)] for x in range(m+1)] 

    # loop through the strings to find the LCS
    for i in range(m+1):
        for j in range(n+1):
            if i == 0 or j == 0:
                # base case
                memoization_table[i][j] = 0
            elif str1[i-1] == str2[j-1]:
                # if the characters match, add 1 to the length
                memoization_table[i][j] = memoization_table[i-1][j-1]+1
            else: 
                # else, take the max of the two previous values
                memoization_table[i][j] = max(memoization_table[i-1][j], memoization_table[i][j-1])

    # construct the LCS
    res = []
    i = m
    j = n
    while i > 0 and j > 0:
        if str1[i-1] == str2[j-1]:
            res.append(str1[i-1])
            i -= 1
            j -= 1
        elif memoization_table[i-1][j] < memoization_table[i][j-1]:
            j -= 1
        else:
            i -= 1
    return ''.join(res[::-1])

