func LongestCommonSubsequence(str1, str2 string) int {
	l1 := len(str1)
	l2 := len(str2)
	result := make([][]int, l1 + 1)
	for i := range result {
		result[i] = make([]int, l2 + 1)
	}

	i, j := 0, 0
	for i = 1; i <= l1; i++ {
		for j = 1; j <= l2; j++ {
			if str1[i-1] == str2[j-1] {
				result[i][j] = result[i-1][j-1] + 1
			} else {
				result[i][j] = max(result[i-1][j], result[i][j-1])
			}
		}
	}

	return result[l1][l2]
}

