 private Node head;

 // Node class
 private class Node {
  String data;
  Node next;

  Node(String data) {
   this.data = data;
   next = null;
  }
 }

 // Add a given value to the head of the list
 public void addAtHead(String value) {
  Node newNode = new Node(value);
  newNode.next = head;
  head = newNode;
