class Stack:

    def __init__(self):
        self.top = None

    def push(self, data):
        if not self.top:
            self.top = Node(data)
        else:
            node = Node(data)
            node.next= self.top
            self.top = node

    def pop(self):
        if self.top == None:
            return None
        data = self.top.data
        self.top = self.top.next
        return data

