class VirtualMachine:
    def __init__(self):
        self.stack = Stack()
        self.input = []
        self.prgrm_counter = 0

    def run_program(self, program):
        self.input = list(program)
        while self.prgrm_counter < len(self.input):
            op = self.input[self.prgrm_counter]
            if op == 'PUSH':
                val = self.input[self.prgrm_counter+1]
                self.stack.push(val)
            elif op == 'ADD':
                val1 = self.stack.pop()
                val2 = self.stack.pop()
                val3 = val1 + val2
                self.stack.push(val3)
            elif op == 'SUBTR':
                val1 = self.stack.pop()
                val2 = self.stack.pop()
                val3 = val1 - val2
                self.stack.push(val3)
            elif op == 'MUL':
                val1 = self.stack.pop()
                val2 = self.stack.pop()
                val3 = val1 * val2
                self.stack.push(val3)
            elif op == 'DIV':
                val1 = self.stack.pop()
                val2 = self.stack.pop()
                val3 = val1 / val2
                self.stack.push(val3)
            elif op == 'PRINT':
                val = self.stack.pop()
                print(val)
            self.prgrm_counter += 1

