def mergeTwoLists(l1: ListNode, l2: ListNode) -> ListNode:
    node = ListNode(0)
    curr = node
    while l1 and l2:
        if l1.val < l2.val:
            curr.next = l1
            l1 = l1.next
        else:
            curr.next = l2
            l2 = l2.next
        curr = curr.next
    curr.next = l1 or l2
    return node.next

