public class CommonAncestor {

 public static Node findAncestor(Node root, Node a, Node b) {
  if (root == null || root == a || root == b) {
   return root;
  }

  Node left = findAncestor(root.left, a, b);
  Node right = findAncestor(root.right, a, b);

  if (left != null && right != null) {
   return root;
  }
  if (left == null && right == null) {
   return null;
  }

  return left == null ? right : left;
 }

 public static void main(String[] args) {
  Node root = new Node('A');
  root.left = new Node('B');
  root.left.left = new Node('D');
  root.left.right = new Node('E');
  root.right = new Node('C');
  root.right.left = new Node('F');
  root.right.right = new Node('G');

  Node commonAncestor = findAncestor(root, root.left.left, root.right.left);

  System.out.println("The common ancestor of D and F is: " + commonAncestor.value);
 }
}

