def generate_parentheses(n):
    result = []
    def gen(s, left, right):
        #base case: if all the parentheses are closed
        if(left == 0 and right == 0):
            result.append(s);
        #case 1: if we can open more parentheses
        if(left > 0): 
            gen(s + '(', left - 1, right)
        #case 2: if we can close more parentheses
        if(right > 0 and left < right):
            gen(s + ')', left, right - 1)
    gen("", n, n)
    return result

