using namespace std;

// Create a NeuralNetwork class
class NeuralNetwork
{
public:
	// Constructor
	NeuralNetwork(int numInputs, int numHiddenNodes, int numOutputs);

	// Train the neural network
	void train(vector<float> inputVals, vector<float> targetVals);

	// Output the results
	void getResults(vector<float> &resultVals);

private:
	int m_numInputs;
	int m_numHiddenNodes;
	int m_numOutputs;

	// Weight matrices
	vector< vector<float> > m_weightsInputToHidden;
	vector< vector<float> > m_weightsHiddenToOutput;
};

// Constructor
NeuralNetwork::NeuralNetwork(int numInputs, int numHiddenNodes, int numOutputs)
{
	m_numInputs = numInputs;
	m_numHiddenNodes = numHiddenNodes;
	m_numOutputs = numOutputs;

	// Create and fill the weight matrices
	// Input to hidden
	m_weightsInputToHidden.resize(m_numInputs);
	for (int i = 0; i < m_numInputs; ++i)
	{
		m_weightsInputToHidden[i].resize(m_numHiddenNodes);
		for (int j = 0; j < m_numHiddenNodes; ++j)
		{
			m_weightsInputToHidden[i][j] = (rand() / (float)RAND_MAX) - 0.5f;
		}
	}

	// Hidden to output
	m_weightsHiddenToOutput.resize(m_numHiddenNodes);
	for (int i = 0; i < m_numHiddenNodes; ++i)
	{
		m_weightsHiddenToOutput[i].resize(m_numOutputs);
		for (int j = 0; j < m_numOutputs; ++j)
		{
			m_weightsHiddenToOutput[i][j] = (rand() / (float)RAND_MAX) - 0.5f;
		}
	}
}

// Train the neural network
void NeuralNetwork::train(vector<float> inputVals, vector<float> targetVals)
{
	// Calculate the hidden nodes' output
	vector<float> hiddenOutputs(m_numHiddenNodes);
	for (int i = 0; i < m_numHiddenNodes; ++i)
	{
		float sum = 0.0f;
		for (int j = 0; j < m_numInputs; ++j)
		{
			sum += inputVals[j] * m_weightsInputToHidden[j][i];
		}
		hiddenOutputs[i] = tanh(sum);
	}

	// Calculate the output nodes' output
	vector<float> outputs(m_numOutputs);
	for (int i = 0; i < m_numOutputs; ++i)
	{
		float sum = 0.0f;
		for (int j = 0; j < m_numHiddenNodes; ++j)
		{
			sum += hiddenOutputs[j] * m_weightsHiddenToOutput[j][i];
		}
		outputs[i] = tanh(sum);
	}
}

// Output the results
void NeuralNetwork::getResults(vector<float> &resultVals)
{
	// Calculate the hidden nodes' output
	vector<float> hiddenOutputs(m_numHiddenNodes);
	for (int i = 0; i < m_numHiddenNodes; ++i)
	{
		float sum = 0.0f;
		for (int j = 0; j < m_numInputs; ++j)
		{
			sum += inputVals[j] * m_weightsInputToHidden[j][i];
		}
		hiddenOutputs[i] = tanh(sum);
	}

	// Calculate the output nodes' output
	resultVals.clear();
	for (int i = 0; i < m_numOutputs; ++i)
	{
		float sum = 0.0f;
		for (int j = 0; j < m_numHiddenNodes; ++j)
		{
			sum += hiddenOutputs[j] * m_weightsHiddenToOutput[j][i];
		}
		resultVals.push_back(tanh(sum));
	}
}

