def search(ll, data):
    # Initialize a reference to the start node
    curr = ll.head
    while curr is not None:
        # Traverse the linked list in both directions
        # And compare each element with the given data
        if curr.data == data:
            return True
        elif curr.next:
            curr = curr.next
        elif curr.previous:
            curr = curr.previous

    return False

