// Function to search for a given element
// in a sorted array using binary search
def binary_search(arr, elem):
    low = 0
    high = len(arr) - 1

    while low <= high:
        mid = low + (high - low) // 2
        if arr[mid] == elem:
            return mid

        elif arr[mid] > elem:
            high = mid - 1

        else:
            low = mid + 1

    return -1

