def all_permutations(original_list):
    if len(original_list) == 0:
        return []

    if len(original_list) == 1:
        return [original_list]

    permutations_list = []
    first_element = original_list[0]

    for counter in range(len(original_list)):
        sub_list = original_list[1:]
        sub_list.insert(counter, first_element)

        sub_permutations = all_permutations(sub_list[1:])

        for permutation in sub_permutations:
            permutation.insert(0,sub_list[0])
            permutations_list.append(permutation)
    return permutations_list

