def toPrefix(exp): 
    operators = {'+':1, '-':1, '*':2, '/':2}
    stack = []
    output = []
    for char in exp:
        if char in operators:
            while(len(stack)>0 and stack[-1] in operators 
            and operators[char]<=operators[stack[-1]]):
                output.append(stack.pop())
            stack.append(char)
        elif char == ")":
            while(len(stack)>0 and stack[-1] !="(" ):
                output.append(stack.pop())
            stack.pop()
        elif char == "(":
            stack.append(char)
        else:
            output.append(char)

    while(len(stack)>0):
        output.append(stack.pop())

    return "".join(output)

