class BinarySearchTree {
    constructor() {
        this.root = null
    }

    add(data) {
        // Create a new node
        const node = new Node(data)
        // Finding the right position in the tree
        if(this.root === null) {
            this.root = node
        } else {
            let current = this.root
            while(true) {
                if(data < current.data) {
                    // Left
                    if(!current.left) {
                        current.left = node
                        break
                    }
                    current = current.left
                } else {
                    // Right
                    if(!current.right) {
                        current.right = node
                        break
                    }
                    current = current.right
                }   
            }
        }
    }
    records() {
        //return an array of all node data
        let records = []
        function traverse(node) {
            records.push(node.data)
            if(node.left) traverse(node.left)
            if(node.right) traverse(node.right)
        }
        traverse(this.root)
        return records
    }
}

